### Interpretation : la valeur se mesure au grounding

La baseline n'est pas un epouvantail : c'est une **vraie sortie de modele** (gpt-5-mini, ~10 800 caracteres, finish=stop, ~2 900 tokens) — une analyse souvent plus lisible que celle du pipeline, qui identifie les sophismes du texte avec des justifications pertinentes. Et elle echoue quand meme aux quatre gates :

- **VG-1** : riche, mais **sans aucune citation `[artifact:...]`** — rien ne permet de remonter d'une affirmation de la synthese a l'artefact qui la porte ;
- **VG-2** : l'appel 0-shot ne construit **aucun artefact** (0 champ peuple) — il n'y a rien a auditer derriere le texte ;
- **VG-3** : sections libres et non tracees — le contenu existe, la forme ancrée sur des artefacts, non ;
- **VG-4** : aucun paragraphe ne croise 2 champs distincts — pas de synthese transversale verifiable.

La lecon en sort durcie : **une analyse eloquente n'est pas une analyse auditable**. Le pipeline lexical n'ecrit pas mieux — mais chaque phrase de sa synthese pointe un artefact construit, verifiable et rejouable. C'est la que se paie l'orchestration : la baseline produit du texte, le pipeline produit une **chaine de tracabilite**. Et la section 4bis a mesure l'autre face : la ou les trois lectures restent muettes, un seul appel agent lit le texte — chaque approche paye ce que l'autre ne sait pas faire (des appels LLM d'un cote, des entrees de lexique de l'autre).

# Cellule [2] - Le moteur JTMS complet (pur stdlib, 0 dependance externe)
from dataclasses import dataclass, field
from typing import List, Dict, Set


@dataclass
class Justification:
    """Une regle de support : `conclusion` est IN ssi
    tout in_list est IN et tout out_list est OUT."""
    conclusion: str
    in_list: List[str] = field(default_factory=list)
    out_list: List[str] = field(default_factory=list)


class JTMS:
    """Justification-based Truth Maintenance System (Doyle 1979, well-founded).

    Les croyances vivent dans un ensemble de noms (str). Les justifications
    forment un graphe oriente. L'etiquetage est un point fixe monotone :
    toutes les croyances partent OUT, puis sont promues IN quand une
    justification valide est trouvee, jusqu'a stabilite.
    """

    def __init__(self):
        self.beliefs: Set[str] = set()
        self.justifications: List[Justification] = []

    def add_belief(self, name: str) -> None:
        self.beliefs.add(name)

    def add_premise(self, name: str) -> None:
        """Une premisse = croyance IN inconditionnellement (listes vides)."""
        self.add_belief(name)
        self.justifications.append(Justification(name, [], []))

    def add_justification(self, conclusion: str,
                          in_list: List[str] = None,
                          out_list: List[str] = None) -> None:
        in_list = in_list or []
        out_list = out_list or []
        self.add_belief(conclusion)
        for b in in_list + out_list:
            self.add_belief(b)
        self.justifications.append(Justification(conclusion, in_list, out_list))

    # --- Etiquetage (well-founded, point fixe monotone) ---
    def label(self) -> Dict[str, str]:
        """Calcule le statut IN/OUT de chaque croyance.

        Monotone : on ne fait que des transitions OUT -> IN, le nombre de
        croyances borne les iterations -> convergence garantie. Les odd loops
        (cycles de support positif) ne sont jamais promus -> restent OUT.
        """
        status = {b: "OUT" for b in self.beliefs}
        changed = True
        while changed:
            changed = False
            for b in self.beliefs:
                if status[b] != "IN":
                    for j in self.justifications:
                        if j.conclusion == b and \
                           all(status[x] == "IN" for x in j.in_list) and \
                           all(status[x] == "OUT" for x in j.out_list):
                            status[b] = "IN"
                            changed = True
                            break
        return status

    # --- Retractation (declenche la cascade au prochain label) ---
    def retract(self, name: str) -> None:
        """Retire toutes les justifications dont la conclusion est `name`.
        Les croyances qui en dependaient perdront leur support -> basculent OUT
        au prochain etiquetage (cascade non-monotone)."""
        self.justifications = [j for j in self.justifications if j.conclusion != name]

    # --- Chaine de retractation (instrument distille du tronc) ---
    def _positive_deps(self) -> Dict[str, Set[str]]:
        """Aretes de dependance POSITIVE : premisse -> conclusion.

        Le `out_list` n'y figure pas : il exprime une defense, pas un soutien.
        """
        deps: Dict[str, Set[str]] = {b: set() for b in self.beliefs}
        for j in self.justifications:
            for x in j.in_list:
                deps.setdefault(x, set()).add(j.conclusion)
        return deps

    def retraction_chain(self, name: str) -> List[Dict[str, object]]:
        """Retracte `name` et rend la cascade **ordonnee**, comme donnee.

        Adapte de `get_retraction_chain` du tronc (services/jtms) : la-bas la
        trace s'accumule au fil de la propagation ; ici l'etiquetage est
        recalcule globalement, donc la chaine est le diff des etiquettes
        (`label()` avant / apres) parcouru en largeur depuis le declencheur.

        Rend une liste de `{'belief', 'cause', 'profondeur'}` : la profondeur
        vaut 0 pour la croyance retractee elle-meme, puis 1 pour ses dependants
        directs, etc. `cause` est la croyance dont la chute a emporte celle-ci
        (`None` pour le declencheur).
        """
        before = self.label()
        self.retract(name)
        after = self.label()
        deps = self._positive_deps()

        chain: List[Dict[str, object]] = [
            {"belief": name, "cause": None, "profondeur": 0}
        ]
        vus = {name}
        frontiere = [name]
        profondeur = 0
        while frontiere:
            profondeur += 1
            suivante = []
            for cause in frontiere:
                for concl in sorted(deps.get(cause, ())):
                    if concl in vus or concl == name:
                        continue
                    if before.get(concl) == "IN" and after.get(concl) == "OUT":
                        chain.append({
                            "belief": concl,
                            "cause": cause,
                            "profondeur": profondeur,
                        })
                        vus.add(concl)
                        suivante.append(concl)
            frontiere = suivante
        return chain

    # --- Detection de circularite (odd loops) ---
    def find_circular(self) -> Set[str]:
        """Croyances OUT dont le seul support est un cycle positif (odd loop).

        On construit le graphe de dependance POSITIVE (on ignore le out_list,
        car un odd loop est un cycle de soutiens mutuels), on en calcule les
        composantes fortement connexes (Tarjan), et on signale les croyances
        OUT appartenant a un cycle non trivial (ou une auto-boucle).
        """
        st = self.label()
        deps = {b: set() for b in self.beliefs}
        for j in self.justifications:
            for x in j.in_list:
                deps[j.conclusion].add(x)

        index_counter = [0]
        stack = []
        on_stack = set()
        index = {}
        lowlink = {}
        sccs = []

        def strongconnect(v):
            index[v] = lowlink[v] = index_counter[0]
            index_counter[0] += 1
            stack.append(v)
            on_stack.add(v)
            for w in deps[v]:
                if w not in index:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], index[w])
            if lowlink[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    on_stack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                sccs.append(comp)

        for v in self.beliefs:
            if v not in index:
                strongconnect(v)

        circular = set()
        for comp in sccs:
            is_cycle = len(comp) > 1 or (len(comp) == 1 and comp[0] in deps[comp[0]])
            if is_cycle and all(st[b] == "OUT" for b in comp):
                circular.update(comp)
        return circular

    # --- Explication d'une croyance (instrument distille du tronc) ---
    def _fondations_perdues(self, name: str, vus=None) -> List[str]:
        """Remonte les fondations OUT sous `name` : la cause racine de la chute.

        Une fondation est une croyance sans justification propre — une regle
        retiree, ou une premisse jamais posee. On descend par les aretes
        positives et on s'arrete sur les cycles.
        """
        vus = vus if vus is not None else set()
        if name in vus:
            return []
        vus.add(name)
        st = self.label()
        regles = [j for j in self.justifications if j.conclusion == name]
        if not regles and st.get(name) == "OUT":
            return [name]
        racines: List[str] = []
        for j in regles:
            for premisse in j.in_list:
                if st.get(premisse) == "OUT":
                    racines.extend(self._fondations_perdues(premisse, vus))
        return sorted(set(racines))

    def explain_belief(self, name: str) -> str:
        """Explique l'etiquetage d'une croyance, regle par regle.

        Adapte de `explain_belief` du tronc : chaque regle concluant vers
        `name` liste ses premices IN/OUT et son verdict. Le verdict distingue
        trois cas, comme le tri-etat du tronc — `valide`, `non concluante
        (circularite)` pour une croyance prise dans un odd loop, `invalide`
        pour un support simplement defait. Une croyance OUT nomme enfin la
        fondation perdue qui a emporte la cascade.
        """
        st = self.label()
        circ = self.find_circular()
        regles = [j for j in self.justifications if j.conclusion == name]
        etat = st.get(name, "?")
        lignes = [f"{name} = {etat}"]
        for j in regles:
            in_status = ", ".join(f"{b} ({st.get(b, '?')})" for b in j.in_list) or "-"
            out_status = ", ".join(f"{b} ({st.get(b, '?')})" for b in j.out_list) or "-"
            soutenue = (all(st.get(b) == "IN" for b in j.in_list)
                        and all(st.get(b) == "OUT" for b in j.out_list))
            if soutenue and not j.in_list and not j.out_list:
                verdict = "valide (premisse : soutien inconditionnel)"
            elif soutenue:
                verdict = "valide"
            elif name in circ:
                verdict = "non concluante (circularite)"
            else:
                verdict = "invalide"
            lignes.append(
                f"  regle : IN=[{in_status}] OUT=[{out_status}] -> {verdict}"
            )
        if not regles:
            lignes.append("  aucune regle : croyance sans soutien")
        if etat == "OUT":
            racines = self._fondations_perdues(name)
            if racines:
                lignes.append(f"  fondation perdue : {', '.join(racines)}")
        return "\n".join(lignes)

    def summary(self) -> str:
        st = self.label()
        lines = [f"  {b:20s} = {st[b]}" for b in sorted(self.beliefs)]
        circ = self.find_circular()
        if circ:
            lines.append(f"  --- circularite detectee : {sorted(circ)}")
        return "\n".join(lines)


print("Moteur JTMS charge (Justification, JTMS) + 2 instruments distilles du tronc (retraction_chain, explain_belief).")

from itertools import chain, combinations


class AF:
    """Cadre d'argumentation abstrait de Dung : <args, attacks>."""

    def __init__(self, args, attacks):
        self.args = set(args)
        self.attacks = set(attacks)  # ensemble de couples (attaquant, attaque)

    def attackers(self, x):
        """Arguments qui attaquent directement x."""
        return {a for (a, b) in self.attacks if b == x}

    def __repr__(self):
        att = ", ".join(f"{a}->{b}" for (a, b) in sorted(self.attacks))
        return f"AF(args={sorted(self.args)}, attacks=[{att}])"


# Un petit exemple ludique pour démarrer : a et b s'attaquent mutuellement.
af0 = AF({"a", "b"}, {("a", "b"), ("b", "a")})
print(af0)
print("Attaquants de a :", af0.attackers("a"))

def is_conflict_free(af, S):
    """True si aucun argument de S n'en attaque un autre dans S."""
    S = set(S)
    for (a, b) in af.attacks:
        if a in S and b in S:
            return False
    return True


print("a,b se battent -> {a,b} sans conflit ?", is_conflict_free(af0, {"a", "b"}))
print("{a} seul  -> sans conflit ?", is_conflict_free(af0, {"a"}))

def defeats(af, S, x):
    """True si S défait x (au moins un membre de S attaque x)."""
    return any((a, x) in af.attacks for a in S)


def defends(af, S, x):
    """True si S défend x : tout attaquant de x est défait par S."""
    return all(defeats(af, S, b) for b in af.attackers(x))


print("Dans af0, {a} défend-il a ?", defends(af0, {"a"}, "a"))
print("  (a est attaqué par b ; {a} défait-il b ? a->b :", ("a", "b") in af0.attacks, ")")

def is_admissible(af, S):
    """True si S est admissible : sans conflit et chacun de ses membres est défendu."""
    S = set(S)
    if not is_conflict_free(af, S):
        return False
    return all(defends(af, S, a) for a in S)


for cand in [set(), {"a"}, {"b"}, {"a", "b"}]:
    print(f"{{{' '.join(sorted(cand)) or '∅'}}} admissible ? {is_admissible(af0, cand)}")

def powerset(args):
    """Tous les sous-ensembles de args, par taille croissante."""
    args = list(args)
    return list(chain.from_iterable(
        combinations(args, r) for r in range(len(args) + 1)
    ))


def grounded(af):
    """Extension grounded : point fixe à partir de l'ensemble vide.

    On ajoute itérativement tout argument défendu par l'ensemble courant, jusqu'à
    ce qu'aucun ajout ne soit plus possible. Le résultat est unique (théorème de Dung).
    """
    S = set()
    changed = True
    while changed:
        changed = False
        for x in af.args:
            if x not in S and defends(af, S, x):
                S.add(x)
                changed = True
    return frozenset(S)


def preferred(af):
    """Extensions preferred : ensembles admissibles maximaux par inclusion."""
    adm = [frozenset(S) for S in powerset(af.args) if is_admissible(af, S)]
    # maximal : aucun autre admissible ne le contient strictement
    return [a for a in adm if not any(a < b for b in adm)]


def stable(af):
    """Extensions stables : admissibles qui défont tout argument hors de l'extension."""
    out = []
    for S in powerset(af.args):
        S = set(S)
        if is_admissible(af, S) and all(
            defeats(af, S, x) for x in af.args if x not in S
        ):
            out.append(frozenset(S))
    return out


def resume(af, label=""):
    """Calcule et affiche les trois sémantiques d'un AF."""
    g = grounded(af)
    p = preferred(af)
    s = stable(af)
    print(f"=== {label or af} ===")
    print(f"  grounded  : {{{', '.join(sorted(g)) or '∅'}}}   (unique, sceptique)")
    print(f"  preferred : {[sorted('{' + ','.join(sorted(e)) + '}') and '{' + ','.join(sorted(e)) + '}' for e in p]}   ({len(p)} ext., crédule)")
    if s:
        print(f"  stable    : {[ '{' + ','.join(sorted(e)) + '}' for e in s]}   ({len(s)} ext.)")
    else:
        print(f"  stable    : AUCUNE (pas d'extension stable)")
    print()
    return g, p, s

