# --- Labels multilingues (skos:prefLabel) + schemes de Walton ---
from collections import Counter

# prefLabel : AnnotationProperty IRI complet (plus d'abbreviatedIRI depuis #763).
pref_pattern = re.compile(
    r'<AnnotationAssertion>\s*<AnnotationProperty IRI="http://www\.w3\.org/2004/02/skos/core#prefLabel"\s*/>\s*<IRI>([^<]+)</IRI>\s*<Literal(?:\s+xml:lang="([^"]+)")?[^>]*>([^<]*)</Literal>\s*</AnnotationAssertion>')
pref_matches = pref_pattern.findall(owl_text)
print(f"skos:prefLabel extraits : {len(pref_matches):,}")
print(f"Langues : {dict(Counter(l.upper() for _, l, _ in pref_matches if l))}")

# dict {localname: {iri, prefLabel:[...]}}
taxonomy = {}
for iri, lang, label in pref_matches:
    local = iri.rstrip('#').split('#')[-1].split('/')[-1]
    if not local:
        continue
    entry = taxonomy.setdefault(local, {'iri': iri, 'prefLabel': []})
    if label:
        entry['prefLabel'].append(label)
print(f"Concepts distincts (par localname) : {len(taxonomy):,}")

# Schemes Walton materialises en classes (#763) -- signal robuste, sans faux positifs de substring.
walton_shaped = sorted(c.split('#')[-1] for c in arg_classes if '_Inference' in c or '_Conflict' in c)
print(f"\nClasses de forme Walton-scheme (materialisation AIF_skos) : {len(walton_shaped)}")
for c in walton_shaped[:8]:
    print(f"  - {c}")

# Detection complementaire par substring dans les prefLabel.
WALTON_SCHEMES = ["Position to Know", "Sign", "Cause to Effect", "Analogy", "Expert Opinion", "Popular Opinion"]
walton_found = {k: [] for k in WALTON_SCHEMES}
for local, entry in taxonomy.items():
    for label in entry.get('prefLabel', []):
        for k in WALTON_SCHEMES:
            if k.lower() in label.lower():
                walton_found[k].append((local, label)); break
print("\nSchemes Walton detectes dans les prefLabel :")
for k in WALTON_SCHEMES:
    hits = walton_found[k]
    print(f"  {'v' if hits else 'x'} {k:18s} : {len(hits)} occurrence(s)")

## 5. Relations : inventaire des AnnotationAssertion-resource

Depuis #763, les relations concept→concept sont portees par des **`AnnotationAssertion`-resource** (et non plus des `ObjectPropertyAssertion`). L'inventaire par predicat revele **trois familles** :

- **hiérarchie SKOS** : `broader` (1 407), `narrower` (1 407), `inScheme` (1 408), `type` (1 409) ;
- **crossLink** (transverse, #141/#763, état dé-curé #1286) : `leverages` (327), `isRelatedTo` (172), `inverts` (82), `allows` (60), `opposes` (50), `predatesOn` (31), `denounces` (9), `mirrors` (4) = **735** au total ;
- **AIF attack** : `aifAttackedNode` (145) → RA/I/CA-node ;
- **mapping Walton** : `broadMatch` (64), `closeMatch` (33), `narrowMatch` (19) = 116.

**Inversion de la note historique** : l'ancien OWL **n'incluait PAS** les 8 verbes crossLink (ils etaient CSV-only). #763 les a **cables et emis** — ce notebook les inventorie donc desormais dans l'OWL.

**Millésime §5** : ces comptes décrivent la **copie vendorée** `ontologies/argumentum_fallacies.owl` **resynchronisée au pin `6bc573f` du sous-module** (passe de re-pin #17669) — le même millésime que la carte (§4bis). L'état précédent (30/08, `ae84c91c` via #13554) portait 1 977 cross-links dont 720 `mirrors` ; la dé-curation amont (#1286/#1247) a retiré ce qui dupliquait l'arbre et ne garde de `mirrors` que la paire `goldenMeanFallacy` ↔ `falseDilemma` (§5.1). Les couches stables n'ont pas bougé : `aifAttackedNode` 145, hiérarchie 1 407/1 407/1 408/1 409.

## 6. Grappe Equivoque : sous-graphe type AIF

L'**Equivoque** (Equivocation) est un sophisme d'ambiguite : un même terme employe dans des sens différents au cours d'un même raisonnement. Dans l'ontologie, le concept `semanticAmbiguity` porte **9 relations** (AnnotationAssertion-resource) :

- hiérarchie : `broader → ambiguity`, `narrower → {vagueness, polysemicLexicalShift, polysemyBySemanticChange}`, `inScheme → fallacyScheme`, `type → Concept` ;
- transverse & mapping : `closeMatch → VagueVerbalClassification_Inference` (Walton), `isRelatedTo → takingAdvantageOfTheNaySayer` ;
- **AIF attack** : `aifAttackedNode → RA-node` — le sophisme est formellement modelise comme une **attaque de l'inference** (RA-node = Rule-Application node au sens AIF, ce qui correspond a un *undercut* ASPIC+).

C'est la demonstration concrete de #763 : **l'AIF est desormais utilisee pour typer les sophismes**, la ou l'ancien OWL se contentait de *declarer* les nodes AIF sans les relier.

from itertools import combinations


class AF:
    """Cadre d'argumentation abstrait de Dung : <args, attacks>."""

    def __init__(self, args, attacks):
        self.args = set(args)
        self.attacks = set(attacks)  # ensemble de couples (attaquant, attaque)

    def attackers(self, x):
        """Arguments qui attaquent directement x."""
        return {a for (a, b) in self.attacks if b == x}

    def __repr__(self):
        att = ", ".join(f"{a}->{b}" for (a, b) in sorted(self.attacks))
        return f"AF(args={sorted(self.args)}, attacks=[{att}])"


# Exemple fil rouge : e n'est pas attaque, a subit 1 attaque, b en subit 3.
af = AF(
    args={"e", "a", "b", "y", "z1", "z2", "z3"},
    attacks={("y", "a"), ("z1", "b"), ("z2", "b"), ("z3", "b")},
)
print(af)
for x in ["e", "a", "b"]:
    print(f"  attaquants de {x} : {sorted(af.attackers(x)) or 'aucun'}")

def h_categoriser(af, tol=1e-12, max_iter=10_000):
    """Calcule le classement h-Categoriser par iteration de point fixe.

    Renvoie (cat, n_iter) ou cat[a] in (0, 1] est la force de a (plus grand = plus fort).
    """
    cat = {a: 1.0 for a in af.args}
    for it in range(1, max_iter + 1):
        nxt = {a: 1.0 / (1.0 + sum(cat[b] for b in af.attackers(a))) for a in af.args}
        delta = max((abs(nxt[a] - cat[a]) for a in af.args), default=0.0)
        cat = nxt
        if delta < tol:
            return cat, it
    return cat, max_iter


cat, n_iter = h_categoriser(af)
print(f"Convergence en {n_iter} iterations.\n")
for a in sorted(af.args, key=lambda a: cat[a], reverse=True):
    print(f"  Cat({a}) = {cat[a]:.4f}")

### Lecture du classement

Le classement induit (force décroissante) départe finement les arguments :

- les **non attaqués** (`e`, `y`, `z1`, `z2`, `z3`) sont au sommet à $1{,}0$ ;
- `a`, attaqué une seule fois par `y` (de force $1$), vaut $\tfrac{1}{1+1} = 0{,}5$ ;
- `b`, attaqué **trois** fois, vaut $\tfrac{1}{1+3} = 0{,}25$.

Donc `a` est **strictement mieux classé** que `b`.

def grounded_extension(af):
    """Plus petit point fixe de la fonction caracteristique (semantique fondee de Dung)."""
    def defends(S, x):
        return all(any((c, b) in af.attacks for c in S) for b in af.attackers(x))

    S = set()
    while True:
        nxt = {a for a in af.args if defends(S, a)}
        if nxt == S:
            return S
        S = nxt


g = grounded_extension(af)
print("Extension fondee :", sorted(g))
print()
# Statut Dung : IN si dans l'extension, OUT si attaque par l'extension, sinon UNDEC.
def dung_status(af, g, x):
    if x in g:
        return "IN"
    if any((c, x) in af.attacks for c in g):
        return "OUT"
    return "UNDEC"

for x in ["a", "b"]:
    print(f"  {x} : statut Dung = {dung_status(af, g, x)}  |  force h-Cat = {cat[x]:.4f}")

def burden_numbers(af, steps=8):
    """Renvoie {a: (Bur^1, ..., Bur^steps)} (Bur^0 = 1 pour tous)."""
    bur = {a: 1.0 for a in af.args}
    seq = {a: [] for a in af.args}
    for _ in range(steps):
        nxt = {a: 1.0 + sum(1.0 / bur[b] for b in af.attackers(a)) for a in af.args}
        for a in af.args:
            seq[a].append(nxt[a])
        bur = nxt
    return {a: tuple(seq[a]) for a in af.args}


def burden_rank(af, steps=8):
    """Classement par fardeau : fardeau lexicographiquement plus petit = plus fort."""
    bn = burden_numbers(af, steps)
    return sorted(af.args, key=lambda a: bn[a]), bn


order, bn = burden_rank(af)
print("Classement par fardeau (du plus fort au plus faible) :")
for rank, a in enumerate(order, 1):
    print(f"  {rank}. {a:3} -> Bur^1..3 = ({bn[a][0]:.3f}, {bn[a][1]:.3f}, {bn[a][2]:.3f})")

